```cpp
#include <iostream>
#include <string>
#include <unordered_map>
#include <regex>

// Markdown to HTML conversion table
const std::unordered_map<std::string, std::string> md2html{
    {"#", "<h1>"},
    {"##", "<h2>"},
    {"###", "<h3>"},
    {"####", "<h4>"},
    {"#####", "<h5>"},
    {"######", "<h6>"},
    {"*", "<em>"},
    {"**", "<strong>"},
    {"`", "<code>"},
    {"[", "<a href=\""],
    {"]", "\"></a>"},
    {"(", "<span class=\"math\">("},
    {")", ")</span>"},
    {"\\ ", " "},  // escape backslash
    {"\n", "<br>\n"},  // line break
    {" ", " "},  // space
    {"---", "<hr>\n"},
    {"___", "<hr>\n"},
    {"**\\*(.*?)\\*\\**", "<i><strong>\\1</strong></i>"},
    {"\\*(.*?)\\*", "<em>\\1</em>"},
    {"\\**(.*?)\\**", "<strong>\\1</strong>"},
    {"\\`(.*?)\\`", "<code>\\1</code>"}
};

std::string markdown_to_html(std::string& markdown) {
    std::string html;

    // Iterate over each character in the input string
    for (char c : markdown) {
        std::string md_token = std::string(1, c);
        auto it = md2html.find(md_token);
        if (it != md2html.end()) {
            // Found a Markdown token, replace it with its corresponding HTML
            html += it->second;
        } else if (std::regex_match(md_token, std::regex("^\\[(.*?)\\]\\((.*?)\\)$"))) {
            // Link: [text](url)
            std::string link_text = std::regex_replace(md_token, std::regex("^\\[(.*?)\\]"), "$1");
            std::string link_url = std::regex_replace(md_token, std::regex("\\((.*?)\\)$"), "$1");
            html += "<a href=\"" + link_url + "\">" + link_text + "</a>";
        } else {
            html += md_token;
        }
    }

    return html;
}

int main() {
    std::string markdown = "## Hello, **Markdown**! [Google](https://google.com) is a great search engine.";
    std::string html = markdown_to_html(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

This implementation uses a lookup table to convert Markdown tokens to their corresponding HTML. It also handles some common Markdown syntax, such as headings, emphasis, code blocks, links, and images.

